\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{booktabs}
\usepackage{array}
\usepackage{microtype}
\pagestyle{empty}

%% ── Color Theme: Dark Navy / Electric Modern ──
\definecolor{primary}{HTML}{0A1628}      % deep navy
\definecolor{secondary}{HTML}{1A56DB}    % electric blue
\definecolor{accent}{HTML}{10B981}       % vibrant green
\definecolor{gold}{HTML}{F59E0B}         % warm amber
\definecolor{bgposter}{HTML}{0D1B2A}     % very dark navy bg
\definecolor{bgcard}{HTML}{162032}       % card background
\definecolor{bgcardalt}{HTML}{1C2A3E}    % alt card background
\definecolor{bgstat}{HTML}{112240}       % stat card bg
\definecolor{titlebar}{HTML}{0A1628}     % same as primary
\definecolor{textlight}{HTML}{E2E8F0}    % light text
\definecolor{textmid}{HTML}{94A3B8}      % mid-tone text
\definecolor{textgray}{HTML}{64748B}     % caption gray
\definecolor{aibadge}{HTML}{1A56DB}      % AI badge blue
\definecolor{aibadgebg}{HTML}{1E3A5F}    % AI badge bg
\definecolor{otherbadgebg}{HTML}{1E2A1E} % other badge bg
\definecolor{otherbadge}{HTML}{10B981}   % other badge green
\definecolor{langpy}{HTML}{3B82F6}       % Python blue
\definecolor{langts}{HTML}{F59E0B}       % TS amber
\definecolor{langrst}{HTML}{EF4444}      % Rust red
\definecolor{langoth}{HTML}{8B5CF6}      % Other purple
\definecolor{rowalt}{HTML}{1A2840}       % table alt row
\definecolor{rowhead}{HTML}{1A56DB}      % table header

\pagecolor{bgposter}

%% ── List styling ──
\setlist[itemize]{leftmargin=20pt,itemsep=4pt,parsep=0pt,topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt,itemsep=6pt,parsep=0pt,topsep=2pt,
  label={\color{gold}\bfseries\arabic*.}}

%% ── Card styles ──
\tcbset{
  navycard/.style={
    enhanced, arc=4pt, boxrule=0.5pt,
    colframe=secondary!40, colback=bgcard,
    left=14pt, right=12pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{textlight},
    coltitle=textlight, colbacktitle=secondary!25!bgcard,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1pt, titlerule style={secondary!50},
    valign=top,
    borderline west={4pt}{0pt}{secondary},
    drop shadow={color=black!60,opacity=0.4},
  },
  greencard/.style={
    enhanced, arc=4pt, boxrule=0.5pt,
    colframe=accent!40, colback=bgcardalt,
    left=14pt, right=12pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{textlight},
    coltitle=textlight, colbacktitle=accent!20!bgcardalt,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1pt, titlerule style={accent!50},
    valign=top,
    borderline west={4pt}{0pt}{accent},
    drop shadow={color=black!60,opacity=0.4},
  },
  goldcard/.style={
    enhanced, arc=4pt, boxrule=0.5pt,
    colframe=gold!50, colback=bgcard,
    left=14pt, right=12pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{textlight},
    coltitle=textlight, colbacktitle=gold!20!bgcard,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1pt, titlerule style={gold!60},
    valign=top,
    borderline west={4pt}{0pt}{gold},
    drop shadow={color=black!60,opacity=0.4},
  },
  highlightcard/.style={
    enhanced, arc=4pt, boxrule=0pt,
    colback=secondary!22!bgcard,
    left=14pt, right=12pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{32}{38}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=secondary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top,
    borderline west={5pt}{0pt}{secondary},
    drop shadow={color=black!70,opacity=0.45},
  },
}

%% ── AI/Other tag badges ──
\newcommand{\aibadge}{%
  \fcolorbox{aibadge}{aibadgebg}{\fontsize{18}{20}\selectfont\bfseries\color{aibadge}~AI~}%
}
\newcommand{\otherbadge}{%
  \fcolorbox{accent}{otherbadgebg}{\fontsize{18}{20}\selectfont\bfseries\color{accent}~OTHER~}%
}

%% ── Language dot ──
\newcommand{\langdot}[2]{%
  {\color{#1}$\bullet$}~{\fontsize{22}{26}\selectfont\color{textmid}#2}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=24, spacing=0mm},
]

%% ════════════════════════════════════════
%% TITLE BAR
%% ════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=secondary!60,
  boxrule=0pt, arc=0pt,
  left=30pt, right=30pt, top=16pt, bottom=14pt,
  halign=center, valign=center,
  borderline south={2pt}{0pt}{secondary},
  drop shadow={color=secondary!30,opacity=0.5},
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{14}{18}\selectfont\bfseries\color{secondary!80}\MakeUppercase{OSS Insight~$\cdot$~24-Hour Trending Analysis}}\\[8pt]
  {\fontsize{68}{80}\selectfont\bfseries\color{white}GitHub's Hottest Repos}\\[4pt]
  {\fontsize{54}{64}\selectfont\bfseries\color{gold}AI Agents Dominate the Charts}\\[12pt]
  {\fontsize{26}{34}\selectfont\color{textmid}A real-time snapshot of open-source momentum $\cdot$ Top 20 repositories ranked by composite score}\\[6pt]
  {\fontsize{22}{28}\selectfont\color{textgray}Data source: OSSInsight.io~$\cdot$~Score~$=$~Stars~$+$~Forks~$+$~Base}
}

%% ════════════════════════════════════════
%% STAT BANNER
%% ════════════════════════════════════════
\posterbox[
  enhanced, colback=bgstat, colframe=secondary!30,
  boxrule=0pt, arc=0pt,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
  borderline south={2pt}{0pt}{secondary!50},
]{name=stats, column=1, span=3, between=row4 and row7}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \vspace{10pt}
    {\fontsize{20}{24}\selectfont\color{textgray}\MakeUppercase{Total GitHub Events Tracked}}\\[4pt]
    {\fontsize{58}{68}\selectfont\bfseries\color{secondary}10.6\,B{\fontsize{36}{44}\selectfont+}}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textmid}across all repos, all time}
    \vspace{10pt}
  \end{minipage}%
  {\color{secondary!30}\rule[-20mm]{1pt}{60mm}}%
  \begin{minipage}[c]{0.31\linewidth}\centering
    \vspace{10pt}
    {\fontsize{20}{24}\selectfont\color{textgray}\MakeUppercase{AI / Agent-Related Repos}}\\[4pt]
    {\fontsize{58}{68}\selectfont\bfseries\color{gold}70\%}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textmid}14 out of 20 trending repos}
    \vspace{10pt}
  \end{minipage}%
  {\color{secondary!30}\rule[-20mm]{1pt}{60mm}}%
  \begin{minipage}[c]{0.31\linewidth}\centering
    \vspace{10pt}
    {\fontsize{20}{24}\selectfont\color{textgray}\MakeUppercase{Top Repo Stars (24h)}}\\[4pt]
    {\fontsize{58}{68}\selectfont\bfseries\color{accent}826}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textmid}andrej-karpathy-skills}
    \vspace{10pt}
  \end{minipage}
}

%% ════════════════════════════════════════
%% TOP 20 TABLE — spans all 3 columns
%% ════════════════════════════════════════
\posterbox[
  navycard, title={{\fontsize{34}{40}\selectfont\bfseries\color{secondary}$\blacksquare$}~~Top 20 Trending Repositories — Past 24 Hours},
]{name=table, column=1, span=3, between=row7 and row21}{
  \fontsize{21}{29}\selectfont\color{textlight}
  \renewcommand{\arraystretch}{1.55}
  \setlength{\tabcolsep}{5pt}
  \begin{tabular}{>{\color{textgray}\bfseries}r
                  >{\color{textlight}\ttfamily}l
                  >{\centering\arraybackslash}m{18mm}
                  >{\centering\arraybackslash}m{14mm}
                  >{\centering\arraybackslash}m{14mm}
                  >{\centering\arraybackslash}m{18mm}
                  >{\centering\arraybackslash}m{20mm}}
    \rowcolor{rowhead}
    \multicolumn{1}{c}{\color{white}\bfseries\#} &
    \multicolumn{1}{c}{\color{white}\bfseries Repository} &
    {\color{white}\bfseries Category} &
    {\color{white}\bfseries Lang} &
    {\color{white}\bfseries Stars} &
    {\color{white}\bfseries Forks} &
    {\color{white}\bfseries Activity} \\
    \rowcolor{rowalt}
    1 & forrestchang/andrej-karpathy-skills & \aibadge & {\color{textgray}—} & {\color{gold}\bfseries 826} & 79 & {\color{textgray}0 pushes} \\
    2 & NousResearch/hermes-agent & \aibadge & {\color{langpy}Py} & {\color{gold}\bfseries 468} & 102 & {\color{accent}66 pushes} \\
    \rowcolor{rowalt}
    3 & NawfalMotii79/PLFM\_RADAR & \otherbadge & {\color{langoth}Verilog} & 353 & 81 & 5 pushes \\
    4 & thedotmack/claude-mem & \aibadge & {\color{langts}TS} & 335 & 33 & 4 pushes \\
    \rowcolor{rowalt}
    5 & VoltAgent/awesome-design-md & \aibadge & {\color{langoth}HTML} & 321 & 49 & {\color{textgray}0 pushes} \\
    6 & JuliusBrussee/caveman & \aibadge & {\color{langpy}Py} & 237 & 19 & {\color{textgray}0 pushes} \\
    \rowcolor{rowalt}
    7 & multica-ai/multica & \aibadge & {\color{langts}TS} & 139 & 13 & {\color{accent}44 pushes} \\
    8 & safishamsi/graphify & \aibadge & {\color{langpy}Py} & 120 & 13 & {\color{textgray}0 pushes} \\
    \rowcolor{rowalt}
    9 & jamiepine/voicebox & \aibadge & {\color{langts}TS} & 100 & 12 & 8 pushes \\
    10 & lsdefine/GenericAgent & \aibadge & {\color{langpy}Py} & 101 & 9 & 5 pushes \\
    \rowcolor{rowalt}
    11 & rohitg00/ai-engineering-from-scratch & \aibadge & {\color{langpy}Py} & 82 & 19 & {\color{textgray}0 pushes} \\
    12 & EvoMap/evolver & \aibadge & {\color{langoth}JS} & 95 & 5 & 1 push \\
    \rowcolor{rowalt}
    13 & google/magika & \aibadge & {\color{langpy}Py} & 122 & 7 & {\color{textgray}0 pushes} \\
    14 & vercel-labs/open-agents & \aibadge & {\color{langts}TS} & 84 & 12 & 2 pushes \\
    \rowcolor{rowalt}
    15 & thunderbird/thunderbolt & \otherbadge & {\color{langts}TS} & 82 & 4 & 7 pushes \\
    16 & alchaincyf/nuwa-skill & \aibadge & {\color{langpy}Py} & 67 & 17 & {\color{textgray}0 pushes} \\
    \rowcolor{rowalt}
    17 & BasedHardware/omi & \otherbadge & {\color{langoth}Dart} & 111 & 72 & 9 pushes \\
    18 & farion1231/cc-switch & \otherbadge & {\color{langrst}Rust} & 77 & 6 & 5 pushes \\
    \rowcolor{rowalt}
    19 & SimoneAvogadro/android-re-skill & \otherbadge & {\color{langoth}Shell} & 77 & 0 & {\color{textgray}0 pushes} \\
    20 & rtk-ai/rtk & \aibadge & {\color{langrst}Rust} & 73 & 4 & 2 pushes \\
  \end{tabular}

  \vspace{8pt}
  {\fontsize{20}{26}\selectfont\color{textgray}Composite score = Stars Score + Forks Score + Base Score.~~{\color{secondary}$\blacksquare$~Blue = AI/Agent-related}~~{\color{accent}$\blacksquare$~Green = Other category}}
}

%% ════════════════════════════════════════
%% COL 1: KEY THEMES
%% ════════════════════════════════════════
\posterbox[navycard, title={Key Themes Driving AI Momentum}
]{name=themes, column=1, span=1, between=row21 and bottom}{
  \fontsize{23}{32}\selectfont\color{textlight}

  \colorbox{aibadgebg}{\parbox{0.94\linewidth}{%
    \vspace{4pt}
    {\color{secondary}\bfseries Autonomous Coding Agents}\\
    multica, open-agents, GenericAgent $\to$ write code \& execute tasks autonomously
    \vspace{4pt}
  }}
  \vspace{6pt}

  \colorbox{bgcardalt}{\parbox{0.94\linewidth}{%
    \vspace{4pt}
    {\color{gold}\bfseries Token Optimization}\\
    caveman, rtk $\to$ slash LLM token use by \textbf{60--90\%}
    \vspace{4pt}
  }}
  \vspace{6pt}

  \colorbox{bgcardalt}{\parbox{0.94\linewidth}{%
    \vspace{4pt}
    {\color{accent}\bfseries Memory \& Context Management}\\
    claude-mem, graphify $\to$ compress sessions into reusable knowledge
    \vspace{4pt}
  }}
  \vspace{6pt}

  \colorbox{bgcardalt}{\parbox{0.94\linewidth}{%
    \vspace{4pt}
    {\color{gold}\bfseries Skill Distillation}\\
    karpathy-skills, nuwa-skill $\to$ expert knowledge as packaged AI skills
    \vspace{4pt}
  }}
}

%% ════════════════════════════════════════
%% COL 2: LANGUAGE BREAKDOWN
%% ════════════════════════════════════════
\posterbox[greencard, title={Language Distribution Among Top 20}
]{name=langs, column=2, span=1, between=row21 and bottom}{
  \fontsize{23}{32}\selectfont\color{textlight}

  %% Bar chart via TikZ (inline)
  \begin{center}
  \begin{tikzpicture}[x=3.6mm, y=8mm]
    % Python bar
    \fill[langpy] (0,3.5) rectangle (7, 4.3);
    \node[right, color=textlight, font=\fontsize{22}{26}\selectfont\bfseries] at (7.3, 3.9) {Python~{\color{langpy}\bfseries 7}~{\color{textgray}(35\%)}};
    % TypeScript bar
    \fill[langts] (0,2.5) rectangle (5, 3.3);
    \node[right, color=textlight, font=\fontsize{22}{26}\selectfont\bfseries] at (5.3, 2.9) {TypeScript~{\color{langts}\bfseries 5}~{\color{textgray}(25\%)}};
    % Rust bar
    \fill[langrst] (0,1.5) rectangle (2, 2.3);
    \node[right, color=textlight, font=\fontsize{22}{26}\selectfont\bfseries] at (2.3, 1.9) {Rust~{\color{langrst}\bfseries 2}~{\color{textgray}(10\%)}};
    % Others bar
    \fill[langoth] (0,0.5) rectangle (6, 1.3);
    \node[right, color=textlight, font=\fontsize{22}{26}\selectfont\bfseries] at (6.3, 0.9) {Others~{\color{langoth}\bfseries 6}~{\color{textgray}(30\%)}};
  \end{tikzpicture}
  \end{center}

  \vspace{6pt}
  \colorbox{bgstat}{\parbox{0.94\linewidth}{%
    \vspace{4pt}\fontsize{22}{30}\selectfont
    {\color{secondary}\bfseries Insight:} Python + TypeScript together account for \textbf{60\%} of trending repos — confirming the AI/ML \& web-tooling stack dominance.
    \vspace{4pt}
  }}
}

%% ════════════════════════════════════════
%% COL 3: ECOSYSTEM SCALE + TAKEAWAY
%% ════════════════════════════════════════
\posterbox[highlightcard, title={The Open-Source AI Infrastructure Race}
]{name=scale, column=3, span=1, between=row21 and bottom}{
  \fontsize{23}{32}\selectfont\color{textlight}

  \begin{itemize}[itemsep=8pt]
    \item \textbf{10.6B+ events} tracked across all GitHub repos — stars, commits, PRs, issues
    \item Composite score weights both {\color{gold}stars} \& {\color{accent}forks}, reflecting broad community adoption
    \item \textbf{70\%} of Top 20 repos target {\color{secondary}AI-augmented dev workflows}
    \item Top 10 repos collectively amassed {\color{gold}\bfseries 3,254 stars} in a single day
    \item The open-source community is racing to build {\color{accent}\bfseries agent autonomy} \& {\color{gold}\bfseries efficiency infrastructure}
  \end{itemize}

  \vspace{8pt}
  \colorbox{primary!60!bgcard}{\parbox{0.94\linewidth}{%
    \vspace{6pt}\fontsize{22}{30}\selectfont\color{white}
    \textbf{Verdict:} Agent autonomy \& token efficiency are the twin priorities of the current open-source wave.
    \vspace{6pt}
  }}

  \vspace{8pt}
  {\fontsize{19}{26}\selectfont\color{textgray}Data: OSSInsight.io~$\cdot$~Period: Past 24h~$\cdot$~All languages}
}

\end{tcbposter}
\end{document}

